#!/usr/bin/env python3
"""Compute ground truth for CSX-178 Q1 from report-supported values."""

from __future__ import annotations

import html
import json
import re
from datetime import date
from pathlib import Path


TASK_ID = "CSX-178_Q1"
EVENT_ID = "CSX-178"
TASK_DIR = Path(__file__).resolve().parent
ROOT = TASK_DIR.parents[2]
PACKAGE = ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUT = TASK_DIR / "computed_gt.json"

ANCHOR_REPORT = "data/event_reports/event_reports_004_Locked_anchor_report_NASA_Earth_Observatory.html"
ANCHOR_JSON = "data/event_reports/event_reports_003_Locked_event_anchor_Nepal_2021_forest_fires.json"


def load_json(relative_path: str) -> dict:
    with (PACKAGE / relative_path).open("r", encoding="utf-8", errors="replace") as handle:
        return json.load(handle)


def load_text(relative_path: str) -> str:
    return (PACKAGE / relative_path).read_text(encoding="utf-8", errors="replace")


def clean_html(raw: str) -> str:
    text = re.sub(r"(?is)<script.*?</script>|<style.*?</style>", " ", raw)
    text = re.sub(r"(?s)<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", html.unescape(text)).strip()


def report_text() -> str:
    raw = load_text(ANCHOR_REPORT)
    paragraphs = re.findall(r"<p[^>]*>(.*?)</p>", raw, flags=re.I | re.S)
    return " ".join(clean_html(paragraph) for paragraph in paragraphs)


def inclusive_days(start: str, end: str) -> int:
    return (date.fromisoformat(end) - date.fromisoformat(start)).days + 1


def parse_reported_hotspots(text: str) -> int:
    match = re.search(r"roughly\s+([0-9,]+)\s+hotspots", text, flags=re.I)
    if not match:
        raise ValueError("hotspot count phrase not found")
    return int(match.group(1).replace(",", ""))


def build_gt() -> dict:
    anchor = load_json(ANCHOR_JSON)
    text = report_text()

    start = anchor["temporal_window"]["start_date"]
    end = anchor["temporal_window"]["end_date"]
    event_days = inclusive_days(start, end)

    reported_rain_fraction = 0.25 if re.search(r"just a quarter of the rain", text, flags=re.I) else None
    if reported_rain_fraction is None:
        raise ValueError("reported rain fraction phrase not found")
    reported_fire_hotspots = parse_reported_hotspots(text)

    smoke_transport_anchors = {
        "smoke_enveloping_country_text": bool(
            re.search(r"smoke enveloping much of the mountainous country", text, flags=re.I)
        ),
        "smoke_pall_pokhara_text": bool(
            re.search(r"smoke pall covering the foothills and valleys near Pokhara", text, flags=re.I)
        ),
        "eastward_smoke_transport_text": bool(
            re.search(r"directs smoke east toward India and Bangladesh", text, flags=re.I)
        ),
    }
    smoke_transport_anchor_count = sum(1 for value in smoke_transport_anchors.values() if value)

    answer = "dry_hotspot_smoke_transport_signature"
    metrics = {
        "reported_rain_fraction_of_normal": reported_rain_fraction,
        "reported_fire_hotspots": reported_fire_hotspots,
        "smoke_transport_anchor_count": smoke_transport_anchor_count,
    }
    computed_implication = (
        "The 0.25 rainfall fraction, roughly 41000 hotspots, and three smoke-transport anchors identify "
        "a dry Nepal fire-smoke episode with broad satellite-observed smoke movement."
    )

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": "reported_numeric_signature",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L2",
        "primary_gt": {
            "answer": answer,
            "metrics": metrics,
            "computed_implication": computed_implication,
        },
        "key_values": {
            "event_window": {"start_date": start, "end_date": end, "inclusive_days": event_days},
            "smoke_transport_anchors": smoke_transport_anchors,
            "hotspot_observation_window": {
                "start_date": "2021-01-01",
                "end_date": "2021-04-07",
                "inclusive_days": inclusive_days("2021-01-01", "2021-04-07"),
            },
            "aliases": [
                "dry_hotspot_smoke_transport_signature",
                "dry_fire_smoke_report_signature",
                "dry_nepal_fire_smoke_signature",
            ],
        },
        "numeric_tolerances": {
            "metrics.reported_rain_fraction_of_normal": 0.001,
            "metrics.reported_fire_hotspots": 500,
            "metrics.smoke_transport_anchor_count": 0,
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "JSON response contract",
                    "points": 3,
                    "description": "Returns parseable JSON with top-level answer, metrics, and computed_implication, and includes all three requested metric keys.",
                    "partial_credit": "Award 1-2 points for a clearly structured response with one missing or renamed field.",
                },
                {
                    "name": "Compact label",
                    "points": 3,
                    "description": "Gives dry_hotspot_smoke_transport_signature or an accepted equivalent centered on dry conditions, hotspot burden, and smoke transport.",
                    "partial_credit": "Award 1-2 points for a wildfire-smoke label that is directionally correct but too generic.",
                },
                {
                    "name": "Reported rainfall fraction",
                    "points": 4,
                    "description": "Extracts that Nepal received just a quarter of normal January-April rainfall and reports 0.25 within 0.001.",
                    "partial_credit": "Award 2-3 points for recognizing a severe rainfall deficit but missing the normalized fraction.",
                },
                {
                    "name": "Reported hotspot count",
                    "points": 3,
                    "description": "Reports approximately 41,000 VIIRS hotspots within 500 detections and treats the value as an approximate detection count.",
                    "partial_credit": "Award 1-2 points for the right order of magnitude or a nearby rounded value outside tolerance.",
                },
                {
                    "name": "Smoke transport anchors",
                    "points": 3,
                    "description": "Counts the three report anchors: smoke enveloping much of Nepal, a smoke pall near Pokhara, and eastward smoke transport toward India and Bangladesh.",
                    "partial_credit": "Award 1 point for each correct anchor.",
                },
                {
                    "name": "Computation-to-label link",
                    "points": 2,
                    "description": "Connects the three values to the final label without adding claims beyond the report-supported numeric signature.",
                    "partial_credit": "Award 1 point for connecting only two of the three values to the label.",
                },
                {
                    "name": "Concise bounded implication",
                    "points": 2,
                    "description": "Gives a one-sentence implication limited to dry conditions, hotspot detections, and smoke transport.",
                    "partial_credit": "Award 1 point if the implication is mostly bounded but includes one minor overstatement.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                ANCHOR_REPORT,
                ANCHOR_JSON,
            ],
            "notes": [
                "Off-event Open-Meteo daily weather and Sentinel-2 dNBR are not used in this ground truth.",
                "The scored values come from the declared event anchor and NASA Earth Observatory report text.",
            ],
        },
    }


def main() -> None:
    OUT.write_text(json.dumps(build_gt(), indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
